const pending=new Map;export function loadVendorScript(n){if(pending.has(n))return pending.get(n);const e=new Promise((e,r)=>{const t=document.createElement("script");t.src=n,t.async=!1,t.onload=()=>e(),t.onerror=()=>r(new Error(`Не удалось загрузить ${n}`)),document.head.appendChild(t)});return pending.set(n,e),e.catch(()=>pending.delete(n)),e}export async function loadVendorScripts(n,e,r){const t=String(n||"").replace(/\/?$/,"/"),o=e.length;for(const[n,c]of e.entries())r?.({file:c,index:n+1,total:o}),await loadVendorScript(t+c)}export function vendorUrl(n,e){return String(n||"").replace(/\/?$/,"/")+e}